import{_ as t,o as s,c as e,a2 as n}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"预算预留","description":"为什么不能\\"先检查预算再付款\\"，以及 AgentPay 如何用原子预留防止并发超支","frontmatter":{"title":"预算预留","description":"为什么不能\\"先检查预算再付款\\"，以及 AgentPay 如何用原子预留防止并发超支"},"headers":[],"relativePath":"zh/learn/04-agentpay-concepts/budget-reservation.md","filePath":"zh/learn/04-agentpay-concepts/budget-reservation.md","lastUpdated":1792490239000}'),i={name:"zh/learn/04-agentpay-concepts/budget-reservation.md"};function l(p,a,r,h,o,d){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="预算预留" tabindex="-1">预算预留 <a class="header-anchor" href="#预算预留" aria-label="Permalink to &quot;预算预留&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">实验性项目</p><p>AgentPay 尚未经过独立安全审计，请勿用于生产环境的真实资金。本页示例均基于测试网和测试代币。</p></div><h2 id="一句话结论" tabindex="-1">一句话结论 <a class="header-anchor" href="#一句话结论" aria-label="Permalink to &quot;一句话结论&quot;">​</a></h2><p><strong>预算检查和预算扣减必须是同一个不可分割的动作。</strong> 先检查、再付款的做法，在并发场景下一定会超支。AgentPay 的做法是&quot;先预留，再付款，最后确认或释放&quot;。</p><h2 id="一个具体的故事" tabindex="-1">一个具体的故事 <a class="header-anchor" href="#一个具体的故事" aria-label="Permalink to &quot;一个具体的故事&quot;">​</a></h2><p>你给 Agent 设置了 24 小时预算 10 USDC。某一时刻，它同时发出两个请求，每个 6 USDC：</p><table tabindex="0"><thead><tr><th>时间</th><th>请求 A</th><th>请求 B</th></tr></thead><tbody><tr><td>t1</td><td>读取剩余预算：10</td><td>读取剩余预算：10</td></tr><tr><td>t2</td><td>10 ≥ 6，通过</td><td>10 ≥ 6，通过</td></tr><tr><td>t3</td><td>付款 6</td><td>付款 6</td></tr><tr><td>结果</td><td></td><td><strong>合计支出 12，超出预算 2</strong></td></tr></tbody></table><p>两个请求都&quot;检查过&quot;了，但都是基于同一个过时的数字。这在 Agent 场景里很常见：一个任务会并行调用多个工具，多个 Agent 也可能共用同一份预算。</p><p>问题出在 t1 到 t3 之间的空隙：<strong>检查和扣减不是同一步。</strong></p><h2 id="几种常见做法-为什么不够" tabindex="-1">几种常见做法，为什么不够 <a class="header-anchor" href="#几种常见做法-为什么不够" aria-label="Permalink to &quot;几种常见做法，为什么不够&quot;">​</a></h2><h3 id="做法一-先检查-再付款" tabindex="-1">做法一：先检查，再付款 <a class="header-anchor" href="#做法一-先检查-再付款" aria-label="Permalink to &quot;做法一：先检查，再付款&quot;">​</a></h3><p>就是上面的故事。检查与付款之间存在窗口，并发请求会同时穿过检查。</p><h3 id="做法二-付款成功后再扣预算" tabindex="-1">做法二：付款成功后再扣预算 <a class="header-anchor" href="#做法二-付款成功后再扣预算" aria-label="Permalink to &quot;做法二：付款成功后再扣预算&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查 → 付款 → 付款成功后扣减</span></span></code></pre></div><p>窗口更大了：从检查到扣减之间，包含了整个付款过程，期间所有并发请求看到的都是旧的预算。</p><h3 id="做法三-在内存里用一个计数器" tabindex="-1">做法三：在内存里用一个计数器 <a class="header-anchor" href="#做法三-在内存里用一个计数器" aria-label="Permalink to &quot;做法三：在内存里用一个计数器&quot;">​</a></h3><p>单进程内可以用锁保护，但 Agent 往往是多进程、多实例运行的，或者进程会重启。内存里的数字既不共享，也不持久，重启之后预算就&quot;回满&quot;了。</p><h3 id="做法四-请求时就扣减-失败了不归还" tabindex="-1">做法四：请求时就扣减，失败了不归还 <a class="header-anchor" href="#做法四-请求时就扣减-失败了不归还" aria-label="Permalink to &quot;做法四：请求时就扣减，失败了不归还&quot;">​</a></h3><p>这能防止超支，但会产生另一个问题：请求失败、被拒绝或超时之后，预算一直被占用，慢慢地把额度&quot;漏光&quot;，Agent 变得无法工作。预留出去的额度必须有明确的去向。</p><h2 id="agentpay-的做法-预留、提交、释放" tabindex="-1">AgentPay 的做法：预留、提交、释放 <a class="header-anchor" href="#agentpay-的做法-预留、提交、释放" aria-label="Permalink to &quot;AgentPay 的做法：预留、提交、释放&quot;">​</a></h2><p>把一次付款对预算的影响拆成三个动作：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        检查额度 + 扣减可用额度      ← 同一个原子操作</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>           预留成功</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>   ┌──────────┼──────────┐</span></span>
<span class="line"><span>   ▼          ▼          ▼</span></span>
<span class="line"><span> 付款成功    明确失败    结果未知</span></span>
<span class="line"><span>   │          │          │</span></span>
<span class="line"><span> 提交确认    释放归还    保持预留</span></span>
<span class="line"><span>（正式计入）（额度恢复）（不动，等待查清）</span></span></code></pre></div><p><strong>第一步：预留（Reserve）。</strong> 检查剩余额度，并把这笔金额划出来，两件事在同一个数据库事务里完成。事务内别的请求看不到中间状态。</p><p><strong>第二步：付款。</strong> 只有预留成功之后，才会进入签名环节。预留失败就直接拒绝，不会产生任何签名。</p><p><strong>第三步：提交或释放。</strong></p><ul><li>付款确认成功 → <strong>提交（Commit）</strong>，预留变成正式支出。</li><li>明确失败，例如被上游以客户端错误拒绝 → <strong>释放（Release）</strong>，额度归还。</li><li>结果未知，例如超时 → <strong>保持预留不动</strong>，等查清之后再决定。这一点与 <a href="./timeout-is-not-failure">超时不等于失败</a> 一致。</li></ul><h3 id="回到开头的故事" tabindex="-1">回到开头的故事 <a class="header-anchor" href="#回到开头的故事" aria-label="Permalink to &quot;回到开头的故事&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求 A：预留 6  → 成功，剩余 4</span></span>
<span class="line"><span>请求 B：预留 6  → 剩余 4 &lt; 6，直接拒绝</span></span></code></pre></div><p>只有一个请求能通过，不会超支。</p><h3 id="它是怎么保证-原子-的" tabindex="-1">它是怎么保证&quot;原子&quot;的 <a class="header-anchor" href="#它是怎么保证-原子-的" aria-label="Permalink to &quot;它是怎么保证&quot;原子&quot;的&quot;">​</a></h3><p>在 AgentPay 里，有两个地方会做预留，原理相同，只是底层实现不同：</p><table tabindex="0"><thead><tr><th>位置</th><th>作用</th><th>实现方式</th></tr></thead><tbody><tr><td><strong>买方本地防火墙</strong></td><td>限制 Agent 自己的支出</td><td>SQLite 事务，写入前先独占锁定数据库</td></tr><tr><td><strong>网关的平台钱包</strong></td><td>限制租户的虚拟钱包扣费</td><td>PostgreSQL 行级锁，同一个钱包的请求严格排队，不同钱包互不影响</td></tr></tbody></table><p>钱包路径上的核心 SQL 是一条带条件的更新：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ap_wallet</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> available_cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> available_cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :amount,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    held_cache      </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> held_cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :amount</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> wallet_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :wallet_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> available_cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :amount;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 受影响行数为 0：余额不足，拒绝</span></span></code></pre></div><p>&quot;检查余额&quot;和&quot;扣减余额&quot;在同一条语句里，数据库保证它们不会被别的请求打断。网关的并发测试里，用 100 个并发请求争抢有限余额，断言可用余额不会透支成负数。</p><h3 id="滚动-24-小时预算" tabindex="-1">滚动 24 小时预算 <a class="header-anchor" href="#滚动-24-小时预算" aria-label="Permalink to &quot;滚动 24 小时预算&quot;">​</a></h3><p>预算窗口用的是<strong>滚动窗口</strong>，而不是&quot;每天零点重置&quot;：</p><ul><li>固定日窗口：23:59 花光 10 USDC，00:01 又可以再花 10 USDC，两分钟内花了 20。</li><li>滚动窗口：任何时刻，往前数 24 小时内的累计支出都不得超过上限。</li></ul><p>滚动窗口能避免在日期边界上被&quot;钻空子&quot;。</p><h3 id="预留也会过期" tabindex="-1">预留也会过期 <a class="header-anchor" href="#预留也会过期" aria-label="Permalink to &quot;预留也会过期&quot;">​</a></h3><p>为了防止上游一直不返回、预留永远占着额度，钱包预留带有超时时间（默认为上游超时再加 60 秒）。到期后由恢复流程统一处理，不会无限期占用。</p><h2 id="配置时的注意事项" tabindex="-1">配置时的注意事项 <a class="header-anchor" href="#配置时的注意事项" aria-label="Permalink to &quot;配置时的注意事项&quot;">​</a></h2><p><strong>一个私钥对应一个账本。</strong> 如果用同一个私钥启动多个 Agent 进程，却让每个进程使用各自独立的本地账本，每个进程都有一份完整的预算，实际总额就是预算乘以进程数。同一个钱包应当共用同一个账本；需要多实例共享预算的场景，使用网关的平台钱包模式更合适。</p><p><strong>金额只用整数。</strong> 所有金额以最小单位的整数表示（USDC 为 6 位小数），数据库里也有整数类型的约束，不使用浮点数，避免累加之后出现精度误差。</p><p><strong>拿不准时拒绝。</strong> 数据库锁等待超时、事务冲突等异常，一律按拒绝处理，宁可少付，不可多付。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：预留了但没付款，额度会不会一直被占着？</strong> 不会。明确失败会立即释放；结果未知的会保持预留，直到查清或到期，由恢复流程处理。</p><p><strong>Q：预算用完之后，Agent 会怎样？</strong> 后续付款会被直接拒绝，并给出明确的原因，不会产生签名。你可以调整上限，或等滚动窗口内的支出滑出。</p><p><strong>Q：并发很高时，行级锁会不会变成瓶颈？</strong> 同一个钱包的预留会排队，但这个事务很短：查询、更新、写入记录后立刻提交，不会在持锁期间等待上游返回。不同钱包之间互不阻塞。</p><p><strong>Q：为什么单笔上限和预算要分开设置？</strong> 它们防的是不同的风险：单笔上限防止一次性付出过大的金额（例如价格被篡改），预算防止许多笔小额累积成大额（例如死循环）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想理解&quot;结果未知时为什么保持预留&quot;：<a href="./timeout-is-not-failure">超时不等于失败</a></li><li>想看到预算拦截的实际效果：<a href="./../05-hands-on/policy-in-action">配置策略并观察拦截</a></li><li>想了解钱包的冻结、确认、释放：<a href="./dual-rail">虚拟钱包与链上支付：双轨架构</a></li></ul><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><ul><li><a href="/docs/specs/wallet-ledger">钱包与账本规范</a>：冻结、确认、释放与对账规则</li><li><a href="/docs/specs/multitenant-data-model">多租户数据模型</a>：钱包与冻结相关的表结构</li><li><a href="/docs/specs/threat-model-v1">威胁模型 v1</a>：并发双花与负余额相关威胁</li><li><a href="/docs/specs/security-model">安全模型</a>：并发预算竞争与单账本约束</li></ul>`,54)])])}const u=t(i,[["render",l]]);export{g as __pageData,u as default};
